finished=$(date -u +%Y-%m-%dT%H:%M:%SZ); result=Fail; IFS=, read -r -a codes <<< "$expected"; for c in "${codes[@]}"; do [[ "$actual" -eq "$c" ]] && result=Pass; done
markdown="openspec/changes/$change/harness/verification.md"; [[ -f "$markdown" && ! -L "$markdown" ]] || { echo '[ERR] unsafe verification Markdown path' >&2; exit 6; }
node - "$verification" "$meta" "$argv_file" "$change" "$task_id" "$kind" "$expected" "$actual" "$result" "$started" "$finished" "$status" "$drift_reason" "${paths[@]}" <<'NODE'
const fs=require('fs'),path=require('path');const [file,metaFile,argvFile,change,taskId,kind,expected,actual,result,started,finished,status,drift,...paths]=process.argv.slice(2),doc=JSON.parse(fs.readFileSync(file)),a=Date.parse(started),z=Date.parse(finished),secret=/(?:authorization|proxy-authorization|bearer|x-?api-?key|api[_-]?key|token|password|secret|cookie|client[_-]?secret|private[_-]?key|access[_-]?key)[\s:=]+\S+|:\/\/[^/\s:]+:[^/@\s]+@|-----BEGIN [A-Z ]*PRIVATE KEY-----/i;if(!Number.isFinite(a)||!Number.isFinite(z)||z<a||Object.keys(doc).some(k=>!['schema_version','change_name','tasks'].includes(k))||doc.schema_version!==1||doc.change_name!==change||!Array.isArray(doc.tasks))process.exit(6);const meta=JSON.parse(fs.readFileSync(metaFile)),argv=JSON.parse(fs.readFileSync(argvFile));if([drift,...argv].some(v=>typeof v==='string'&&secret.test(v)))throw Error('secret-like Generator evidence');let t=doc.tasks.find(x=>x.task_id===taskId);if(!t){t={task_id:taskId,requirement_refs:meta.requirement_refs,changed_paths:[],footprint_observation:{},commands:[]};doc.tasks.push(t)}t.requirement_refs=meta.requirement_refs;t.changed_paths=[...new Set([...t.changed_paths,...paths])].sort();t.footprint_observation={status,drift_reason:drift||null};t.commands.push({id:'gen-cmd-'+Date.now()+'-'+process.pid,kind,argv,working_directory:'.',started_at:started,finished_at:finished,expected_exit_codes:expected.split(',').map(Number),exit_code:Number(actual),result});doc.tasks.sort((a,b)=>a.task_id.localeCompare(b.task_id,undefined,{numeric:true}));const tmp=path.join(path.dirname(file),'.verification-'+process.pid+'-'+Date.now());fs.writeFileSync(tmp,JSON.stringify(doc,null,2)+'\n',{mode:0o644,flag:'wx'});fs.renameSync(tmp,file);
NODE
node - "$verification" "$markdown" <<'NODE'
const fs=require('fs'),path=require('path');const [jsonFile,file]=process.argv.slice(2),d=JSON.parse(fs.readFileSync(jsonFile));let out=`# Verification — ${d.change_name}\n\n`;for(const t of d.tasks){out+=`## Task ${t.task_id}\n\n- Changed paths: ${t.changed_paths.length?t.changed_paths.join(', '):'<none>'}\n- Footprint: ${t.footprint_observation.status}`+(t.footprint_observation.drift_reason?` — ${t.footprint_observation.drift_reason}`:'')+'\n\n';for(const c of t.commands)out+=`- ${c.id}: ${c.kind} ${c.result} (exit ${c.exit_code}; expected ${c.expected_exit_codes.join(',')})\n`;out+='\n'}const tmp=path.join(path.dirname(file),'.verification-md-'+process.pid+'-'+Date.now());fs.writeFileSync(tmp,out,{mode:0o644,flag:'wx'});fs.renameSync(tmp,file);
NODE
[[ "$result" == Pass ]]
